/* Independent M11 native supplement. Frozen before candidate inspection. */
#include "support_m11.h"
static const char plain[]="struct Shape { a:u32, } @compute @workgroup_size(1) fn boundary(){}";
static const char roots[]="struct Shape { a:u32, } var<workgroup> anonymous:array<vec2<u32>,3>; var<workgroup> named:Shape; @compute @workgroup_size(1) fn boundary(){}";
static const char root_only[]="var<workgroup> root:array<u32,3>; @compute @workgroup_size(1) fn boundary(){root[0u]=1u;workgroupBarrier();}";
static const unsigned modes[]={1u,2u,3u,5u,6u,7u};
static int workspace_boundaries(void){
 DoeCompilerWorkspaceRequirements r;CHECK(doe_compiler_workspace_requirements(2u,&r,sizeof(r))==DOE_COMPILER_OK,"fixed query");CHECK(r.size_bytes==146256u&&r.alignment_bytes==8u,"frozen fixed layout exact");
 Guard work,words;CHECK(guard_new(&work,r.size_bytes)==0&&guard_new(&words,4096u*4u)==0,"fixed guards");DoeCompilerResultV2 result;
 const size_t lengths[]={140056u,r.size_bytes-1u};
 for(unsigned i=0;i<COUNT(lengths);++i){guard_mark(&work);guard_mark(&words);memset(&result,MARK,sizeof(result));CHECK(doe_compiler_compile_v2(2u,work.data,lengths[i],root_only,strlen(root_only),(uint32_t*)words.data,4096u,&result,sizeof(result))==DOE_COMPILER_INPUT_ERROR,"stale/short fixed workspace rejects");CHECK(bytes_are(work.data,work.bytes,MARK)&&bytes_are(words.data,words.bytes,MARK),"workspace preflight no writes");CHECK(result.word_count==0u,"workspace failure unpublished");}
 CHECK(doe_compiler_compile_v2(2u,work.data,r.size_bytes,root_only,strlen(root_only),(uint32_t*)words.data,4096u,&result,sizeof(result))==DOE_COMPILER_OK,"exact fixed workspace with workgroup");CHECK(guard_ok(&work)&&guard_ok(&words),"fixed redzones");guard_free(&work);guard_free(&words);
 const DoeCompilerJobCapacities job={65536u,8192u,1024u,4096u,65536u,32u,16u};CHECK(doe_compiler_job_requirements(3u,&job,sizeof(job),&r,sizeof(r))==DOE_COMPILER_OK,"old job query");CHECK(r.size_bytes==2172992u&&r.alignment_bytes==8u,"frozen old-job CLI layout exact");
 CHECK(guard_new(&work,r.size_bytes)==0&&guard_new(&words,4096u*4u)==0,"job guards");CHECK(doe_compiler_compile_job(3u,&job,sizeof(job),work.data,1997144u,root_only,strlen(root_only),(uint32_t*)words.data,4096u,&result,sizeof(result))==DOE_COMPILER_INPUT_ERROR,"stale M10 old job rejects");CHECK(bytes_are(work.data,work.bytes,MARK)&&bytes_are(words.data,words.bytes,MARK),"stale old job preflight no writes");CHECK(doe_compiler_compile_job(3u,&job,sizeof(job),work.data,r.size_bytes-1u,root_only,strlen(root_only),(uint32_t*)words.data,4096u,&result,sizeof(result))==DOE_COMPILER_INPUT_ERROR,"short old job rejects");CHECK(bytes_are(work.data,work.bytes,MARK)&&bytes_are(words.data,words.bytes,MARK),"old job preflight no writes");CHECK(doe_compiler_compile_job(3u,&job,sizeof(job),work.data,r.size_bytes,root_only,strlen(root_only),(uint32_t*)words.data,4096u,&result,sizeof(result))==DOE_COMPILER_OK,"exact old job with workgroup");CHECK(guard_ok(&work)&&guard_ok(&words),"old job redzones");guard_free(&work);guard_free(&words);
 DoeCompilerResult r1;uint32_t fixedwords[4096];CHECK(doe_compiler_compile(1u,root_only,strlen(root_only),fixedwords,COUNT(fixedwords),&r1,sizeof(r1))==DOE_COMPILER_OK,"ABI1 anonymous workgroup hidden from legacy projection");return 0;
}
static int typed_boundaries(void){
 Client c;CHECK(client_new(&c,&generous)==0,"typed client");CHECK(c.req.size_bytes==2536128u&&c.req.alignment_bytes==8u,"frozen typed CLI exact");DoeCompilerTypedResult base,rich;guard_mark(&c.workspace);CHECK(doe_compiler_compile_typed(4u,&c.caps,sizeof(c.caps),c.workspace.data,2510488u,roots,strlen(roots),7u,NULL,0u,&rich,sizeof(rich))==DOE_COMPILER_INPUT_ERROR,"stale M10 typed workspace rejects");CHECK(bytes_are(c.workspace.data,c.workspace.bytes,MARK),"stale typed preflight no writes");CHECK(invoke(&c,plain,strlen(plain),7u,NULL,&base)==DOE_COMPILER_OK,"plain measure");CHECK(invoke(&c,roots,strlen(roots),7u,NULL,&rich)==DOE_COMPILER_OK,"roots measure");CHECK(rich.required.words>base.required.words,"root target declarations and prologue exist");CHECK(rich.required.types==base.required.types&&rich.required.members==base.required.members&&rich.required.resources==base.required.resources&&rich.required.name_bytes==base.required.name_bytes,"workgroup roots do not alter reflection closure");CHECK(rich.required.resources==0u,"workgroup roots not descriptors");DoeCompilerTypedOutputCounts expected=rich.required;
 Bulk b,p;CHECK(bulk_new(&b,&rich.required)==0&&bulk_new(&p,&base.required)==0,"exact output allocations");CHECK(invoke(&c,plain,strlen(plain),2u,&p.o,&base)==DOE_COMPILER_OK,"plain reflection");CHECK(invoke(&c,roots,strlen(roots),2u,&b.o,&rich)==DOE_COMPILER_OK,"root reflection");for(unsigned i=1u;i<5u;++i)CHECK(memcmp(b.span[i].data,p.span[i].data,b.span[i].bytes)==0,"anonymous roots leave public reflection bytes unchanged");
 for(unsigned i=0;i<COUNT(modes);++i){unsigned flags=modes[i];DoeCompilerTypedOutputs o=selected(&b,flags);bulk_mark(&b);CHECK(invoke(&c,roots,strlen(roots),flags,(flags&4u)?NULL:&o,&rich)==DOE_COMPILER_OK,"all modes process roots");CHECK(rich.required_is_exact==1u&&rich.required.words==((flags&1u)?expected.words:0u),"all modes selected exact counts");CHECK(rich.required.types==((flags&2u)?expected.types:0u),"selected exact reflection counts");CHECK(bulk_guards(&b)&&guard_ok(&c.workspace),"mode guards");
  bulk_mark(&b);memset(&rich,MARK,sizeof(rich));CHECK(invoke(&c,semantic_source,strlen(semantic_source),flags,(flags&4u)?NULL:&o,&rich)==DOE_COMPILER_SEMANTIC_ERROR,"every mode rejects nonuniform barrier");CHECK(failure_result(&rich,DOE_COMPILER_SEMANTIC_ERROR,0)==0&&bulk_unchanged(&b),"uniformity failure atomic");CHECK(strstr(rich.diagnostic.message,"uniform")!=NULL,"uniformity diagnostic");CHECK(rich.diagnostic.offset<strlen(semantic_source),"original source location");
 }
 bulk_mark(&b);DoeCompilerTypedOutputs o=b.o;o.word_capacity=expected.words-1u;CHECK(invoke(&c,roots,strlen(roots),3u,&o,&rich)==DOE_COMPILER_OUTPUT_TOO_SMALL,"one-short words with roots");CHECK(failure_result(&rich,DOE_COMPILER_OUTPUT_TOO_SMALL,1)==0&&bulk_unchanged(&b),"one-short atomic");CHECK(invoke(&c,roots,strlen(roots),3u,&b.o,&rich)==DOE_COMPILER_OK,"exact words after failure");
 bulk_free(&p);bulk_free(&b);client_free(&c);return 0;
}
int main(void){CHECK(native_allocator_control()==0,"allocator control");CHECK(workspace_boundaries()==0,"workspace boundary matrix");CHECK(typed_boundaries()==0,"typed boundary matrix");CHECK(atomic_load(&native_allocations)==0u,"library allocation-free");puts("PASS M11 fixed/current/stale workspaces, hidden roots, all-mode uniformity atomicity and exact outputs");return 0;}
